css:
.invoice-container {
  font-family: Arial, sans-serif;
  font-size: 10px;
  border: 1px solid #000;
  margin: 0;
  padding: 5px;
  width: 100%;
}
table {
  width: 100%;
  border-collapse: collapse;
  font-size:10px;
}
th, td {
  border: 1px solid #000;
  padding: 6px 8px;
  vertical-align: top;
}
th {
  background: #f2f2f2;
  text-align: center;
}
.center { text-align: center; }
.right { text-align: right; }
.bold { font-weight: bold; }
.no-border { border: none !important; }
.logo {
  width: 80px;
  height: 50px;
  border: 1px solid #ccc;
  background: #f9f9f9;
  padding:1px;
  margin:1px;
}
.signature {
  text-align: right;
  padding: 20px 10px;
  font-size: 10px;
}

.padding_td {
  margin: 2px 0;
  display: flex;
  align-items: flex-start;
}

.padding_td  b {
  min-width: 20px;   /* Adjust width depending on longest label */
  margin-right: 5px;  /* Gap between label and value */
  display: inline-block;
  white-space: nowrap;
}

@media print {
  body { margin: 0; }
  .invoice-container { border: none; }
  thead { display: table-header-group; }
  table { page-break-inside: avoid; }
}
